    # Bars are threaded together into the output path. Horizontal tile lengths
    # are color-coded (1:3, 2:2, 3:4); each 6 tile is a vertical pair.
    # Track the joining edge as the sequence proceeds.
    row = mr + 1
    for idx, color in enumerate(tiles):
