    mr, x = marker
    out[mr][x] = 5
    tiles = []
    # Read each tile row-band from left to right.
    for top in range(0, h - 2, 4):
        for left in (0, 4):
            vals = [grid[r][c] for r in range(top, top + 3) for c in range(left, left + 3) if grid[r][c] not in (0, 4, 5)]
            if vals:
                tiles.append(vals[0])
    # Render the line encoded by each tile. The color specifies line length,
    # while the source tile position determines the initial lane.
    row = mr + 1
    for color in tiles:
        if row >= h:
            break
        if color == 6:
            col = 4
            out[row][col] = 6
            if row + 1 < h:
                out[row + 1][col] = 6
            row += 2
        else:
            length = {1: 3, 2: 2, 3: 4}[color]
            start = {1: 2, 2: 3, 3: 1}[color]
            for c in range(start, start + length):
                out[row][c] = color
            row += 1
