 "content": "def transform(grid):
    # Remove the divider and interpret each 3x3 tile as a line glyph.
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    marker = next(((r, c - 8) for r, row in enumerate(grid)
                   for c, v in enumerate(row) if v == 5), (0, 2))
    mr, anchor = marker
    out[mr][anchor] = 5

    # Tiles are arranged in 4-row bands: left and right motif within each band.
    tiles = []
    for top in range(0, h - 2, 4):
        for left in (0, 4):
            vals = [grid[r][c] for r in range(top, top + 3)
                    for c in range(left, left + 3)
                    if grid[r][c] not in (0, 4, 5)]
            if vals:
                tiles.append((top, left, vals[0]))

    # Each motif is converted into its matching straight-stroke shape, at its
    # original band; the x-track alternates to follow the motif's line endpoint.
    for top, left, color in tiles:
        row = top + 1
        if color == 6:
            col = 4 if left == 0 else 2
            out[row][col] = 6
            if row + 1 < h:
                out[row + 1][col] = 6
        elif color == 1:
            start = 2 if left == 0 else 3
            for c in range(start, start + 3):
                out[row][c] = 1
        elif color == 2:
            start = 3 if left == 0 else 2
            for c in range(start, start + 2):
                out[row][c] = 2
        elif color == 3:
            start = 1 if left == 0 else 2
            for c in range(start, start + 4):
                out[row][c] = 3
